PRICE_PER_BOOK = 800
DISCOUNTS = {1: 0, 2: 5, 3: 10, 4: 20, 5: 25}
GROUP_PRICES = {
    size: size * PRICE_PER_BOOK * (100 - DISCOUNTS[size]) // 100
    for size in DISCOUNTS
}


def total(basket):
    """Return the lowest possible price (in cents) for the given basket."""
    counts = [basket.count(title) for title in range(1, 6)]
    total = 0
    while any(counts):
        counts.sort(reverse=True)
        distinct = sum(1 for count in counts if count > 0)
        if distinct == 5:
            # Two groups of four (2560 + 2560) beat a group of five plus a
            # group of three (3000 + 2160). Prefer a group of four when the
            # most-copied titles outnumber the least-copied ones; otherwise
            # a full group of five is best.
            most = counts[0]
            least = counts[4]
            if most > least:
                n_most = sum(1 for count in counts if count == most)
                n_least = sum(1 for count in counts if count == least)
                group = 4 if n_most >= n_least else 5
            else:
                group = 5
        else:
            group = distinct
        total += GROUP_PRICES[group]
        for i in range(group):
            counts[i] -= 1
    return total

